-- =============================================================================
-- Staff time clock, schedule and store credit (update 15)
-- =============================================================================
-- Student employees clock in and out at /clock with a 4-digit PIN (or by
-- scanning their student ID). Staff schedule them by class hour (1st–7th hour,
-- the class hours in Settings) and every employee earns store credit for the
-- time they work: $1 for every 45 minutes (both numbers are settings).
--
--   staff                  employees: name, PIN, optional badge (student ID #).
--                          status: pending (signed up at /clock, waiting for
--                          approval) → active → removed (can be restored or erased).
--   staff_shifts           timecards: one row per shift, clock_in → clock_out.
--                          Keeps the employee's name, so hours survive erasing them.
--   staff_schedule         who works which class hour on which day.
--   staff_credit_entries   store credit spent (minus) or added by hand (plus).
--                          Credit EARNED isn't stored: it's worked out from the
--                          timecards, so fixing a shift fixes the credit too.
--   staff_clock_attempts   wrong PINs and sign-ups per device, for rate limiting.
--
--   staff_punch()          clock in / out with a PIN or badge     (website server only)
--   staff_punch_undo()     undo a punch within 2 minutes           (website server only)
--   staff_signup()         "Create account" on the time clock      (website server only)
--   staff_board()          on the clock, today's shifts, upcoming schedule (server only)
--   staff_credit_balances()  credit earned / used / left per employee (admin, server)
--   staff_credit_add()     spend or add credit (admin; can't go below $0)
--
-- Students can't read any of these tables. The time clock page talks to the
-- database only through the website's server, which hashes the device's IP for
-- the rate limits, the same way orders do.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Settings
-- -----------------------------------------------------------------------------
alter table public.settings
  add column staff_credit_cents    int     not null default 100 check (staff_credit_cents between 0 and 2000),
  add column staff_credit_minutes  int     not null default 45  check (staff_credit_minutes between 5 and 480),
  add column staff_signup_approval boolean not null default true;


-- -----------------------------------------------------------------------------
-- 2. Tables
-- -----------------------------------------------------------------------------
create table public.staff (
  id           uuid primary key default gen_random_uuid(),
  name         text not null check (char_length(name) between 2 and 40),
  pin          text not null check (pin ~ '^[0-9]{4}$'),
  badge        text check (badge is null or char_length(badge) between 1 and 40),
  status       text not null default 'active' check (status in ('pending', 'active', 'removed')),
  self_signup  boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
-- Two people who can clock in can't share a PIN or a badge.
create unique index staff_pin_in_use   on public.staff (pin)          where status <> 'removed';
create unique index staff_badge_in_use on public.staff (lower(badge)) where status <> 'removed' and badge is not null;

create table public.staff_shifts (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid references public.staff (id) on delete set null,
  staff_name  text not null,
  clock_in    timestamptz not null,
  clock_out   timestamptz check (clock_out is null or clock_out >= clock_in),
  manual      boolean not null default false,   -- added or fixed by staff, not punched
  undo_token  text,
  undo_kind   text check (undo_kind in ('in', 'out')),
  undo_until  timestamptz,
  created_at  timestamptz not null default now()
);
-- Nobody can be clocked in twice at once.
create unique index staff_shifts_one_open on public.staff_shifts (staff_id) where clock_out is null;
create index on public.staff_shifts (clock_in desc);
create index on public.staff_shifts (staff_id, clock_in);

create table public.staff_schedule (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid not null references public.staff (id) on delete cascade,
  work_date   date not null,
  window_id   int  not null references public.pickup_windows (id) on delete cascade,
  note        text check (note is null or char_length(note) <= 80),
  created_at  timestamptz not null default now(),
  unique (staff_id, work_date, window_id)
);
create index on public.staff_schedule (work_date, window_id);

create table public.staff_credit_entries (
  id            uuid primary key default gen_random_uuid(),
  staff_id      uuid not null references public.staff (id) on delete cascade,
  amount_cents  int  not null check (amount_cents <> 0 and amount_cents between -100000 and 100000),
  note          text check (note is null or char_length(note) <= 120),
  created_at    timestamptz not null default now()
);
create index on public.staff_credit_entries (staff_id, created_at desc);

create table public.staff_clock_attempts (
  ip_hash     text not null,
  kind        text not null check (kind in ('pin', 'signup')),
  created_at  timestamptz not null default now()
);
create index on public.staff_clock_attempts (ip_hash, kind, created_at);


-- -----------------------------------------------------------------------------
-- 3. Store credit
-- -----------------------------------------------------------------------------
-- Per employee: minutes worked (finished shifts), credit earned from them,
-- credit added/used by hand, what's left, and minutes until the next dollar.
-- Runs as the caller, so Row Level Security decides who sees what (the admin
-- sees everyone; students see nothing).
create or replace function public.staff_credit_balances()
returns table (
  staff_id            uuid,
  worked_minutes      int,
  earned_cents        int,
  adjust_cents        int,
  balance_cents       int,
  next_credit_minutes int
)
language sql stable
set search_path = public
as $$
  with rate as (
    select staff_credit_cents as cents, staff_credit_minutes as minutes from public.settings where id = 1
  ),
  worked as (
    select sh.staff_id, floor(sum(extract(epoch from (sh.clock_out - sh.clock_in))) / 60)::int as minutes
      from public.staff_shifts sh
     where sh.clock_out is not null and sh.staff_id is not null
     group by sh.staff_id
  ),
  adjusted as (
    select e.staff_id, sum(e.amount_cents)::int as cents from public.staff_credit_entries e group by e.staff_id
  )
  select s.id,
         coalesce(w.minutes, 0),
         (coalesce(w.minutes, 0) / rate.minutes) * rate.cents,
         coalesce(a.cents, 0),
         (coalesce(w.minutes, 0) / rate.minutes) * rate.cents + coalesce(a.cents, 0),
         rate.minutes - (coalesce(w.minutes, 0) % rate.minutes)
    from public.staff s
    cross join rate
    left join worked   w on w.staff_id = s.id
    left join adjusted a on a.staff_id = s.id;
$$;

-- Staff record credit an employee used at the window (a minus amount), or add
-- some by hand (a plus amount). Using more than they have is refused.
create or replace function public.staff_credit_add(p_staff_id uuid, p_amount_cents int, p_note text)
returns int
language plpgsql security definer
set search_path = public
as $$
declare
  v_balance int;
begin
  if not public.is_admin() then
    raise exception 'Only staff can change store credit.';
  end if;
  if p_amount_cents is null or p_amount_cents = 0 or abs(p_amount_cents) > 100000 then
    raise exception 'Enter an amount.';
  end if;
  perform 1 from public.staff where id = p_staff_id for update;
  if not found then
    raise exception 'That employee is gone.';
  end if;
  select balance_cents into v_balance from public.staff_credit_balances() where staff_id = p_staff_id;
  if v_balance + p_amount_cents < 0 then
    raise exception 'Only $% of credit left.', to_char(v_balance / 100.0, 'FM999990.00');
  end if;
  insert into public.staff_credit_entries (staff_id, amount_cents, note)
  values (p_staff_id, p_amount_cents, nullif(left(btrim(coalesce(p_note, '')), 120), ''));
  return v_balance + p_amount_cents;
end;
$$;


-- -----------------------------------------------------------------------------
-- 4. The time clock (called only by the website's server)
-- -----------------------------------------------------------------------------

-- An employee's next scheduled class hour that hasn't started yet, or null.
create or replace function public.staff_next_shift(p_staff_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object('date', sc.work_date, 'label', w.label, 'startsAt', to_char(w.starts_at, 'HH24:MI'))
    from public.staff_schedule sc
    join public.pickup_windows w on w.id = sc.window_id
   where sc.staff_id = p_staff_id
     and (sc.work_date > public.store_today()
          or (sc.work_date = public.store_today() and w.starts_at > public.store_now_time()))
   order by sc.work_date, w.starts_at
   limit 1;
$$;

-- Clock in or out. p_code is a 4-digit PIN or a scanned badge.
-- Returns { status: 'in' | 'out' | 'pending', name, ... } or { error, code }.
create or replace function public.staff_punch(p_code text, p_ip_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_code   text := btrim(coalesce(p_code, ''));
  v_now    timestamptz := now();
  v_tz     text := (select timezone from public.settings where id = 1);
  v_week   timestamptz;
  v_staff  public.staff;
  v_open   public.staff_shifts;
  v_id     uuid;
  v_in     timestamptz;
  v_token  text := replace(gen_random_uuid()::text, '-', '');
  v_status text;
  v_credit record;
begin
  v_week := date_trunc('week', v_now at time zone v_tz) at time zone v_tz;  -- Monday, 12:00 AM

  -- 8 wrong tries in 15 minutes locks this device out for a while.
  if p_ip_hash is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = p_ip_hash and kind = 'pin' and created_at > v_now - interval '15 minutes'
  ) >= 8 then
    return jsonb_build_object('error', 'Too many wrong tries. Wait 15 minutes or ask a manager.', 'code', 'LOCKED');
  end if;

  if v_code <> '' and char_length(v_code) <= 40 then
    select * into v_staff from public.staff
     where status <> 'removed' and (pin = v_code or (badge is not null and lower(badge) = lower(v_code)))
     limit 1;
  end if;

  if v_staff.id is null then
    if p_ip_hash is not null then
      insert into public.staff_clock_attempts (ip_hash, kind) values (p_ip_hash, 'pin');
    end if;
    delete from public.staff_clock_attempts where created_at < v_now - interval '1 day';
    return jsonb_build_object('error', 'No account has that PIN. Try again, or tap Create account if you''re new.', 'code', 'NOT_FOUND');
  end if;

  if v_staff.status = 'pending' then
    return jsonb_build_object('status', 'pending', 'name', v_staff.name);
  end if;

  select * into v_open from public.staff_shifts where staff_id = v_staff.id and clock_out is null for update;
  if v_open.id is not null then
    update public.staff_shifts
       set clock_out = v_now, undo_token = v_token, undo_kind = 'out', undo_until = v_now + interval '2 minutes'
     where id = v_open.id;
    v_id := v_open.id; v_in := v_open.clock_in; v_status := 'out';
  else
    insert into public.staff_shifts (staff_id, staff_name, clock_in, undo_token, undo_kind, undo_until)
    values (v_staff.id, v_staff.name, v_now, v_token, 'in', v_now + interval '2 minutes')
    returning id into v_id;
    v_in := v_now; v_status := 'in';
  end if;

  select * into v_credit from public.staff_credit_balances() b where b.staff_id = v_staff.id;

  return jsonb_build_object(
    'status', v_status,
    'name', v_staff.name,
    'in', v_in,
    'out', case when v_status = 'out' then v_now end,
    'id', v_id,
    'undo', v_token,
    'weekMinutes', (
      select coalesce(floor(sum(extract(epoch from (coalesce(clock_out, v_now) - clock_in))) / 60), 0)::int
        from public.staff_shifts where staff_id = v_staff.id and clock_in >= v_week
    ),
    'creditCents', coalesce(v_credit.balance_cents, 0),
    'nextCreditMinutes', v_credit.next_credit_minutes,
    'next', public.staff_next_shift(v_staff.id)
  );
end;
$$;

-- Undo a punch (tapped by mistake) within 2 minutes.
create or replace function public.staff_punch_undo(p_shift_id uuid, p_token text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_shift public.staff_shifts;
begin
  select * into v_shift from public.staff_shifts
   where id = p_shift_id and undo_token = p_token and undo_until > now()
   for update;
  if v_shift.id is null then
    return jsonb_build_object('error', 'Too late to undo. Ask a manager to fix it.');
  end if;
  if v_shift.undo_kind = 'in' then
    delete from public.staff_shifts where id = v_shift.id;
  else
    begin
      update public.staff_shifts set clock_out = null, undo_token = null, undo_kind = null, undo_until = null where id = v_shift.id;
    exception when unique_violation then
      return jsonb_build_object('error', 'You''re already clocked in again. Ask a manager to fix it.');
    end;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- "Create account" on the time clock. New accounts wait for approval unless
-- that's switched off (Admin → Employees).
create or replace function public.staff_signup(p_name text, p_pin text, p_badge text, p_ip_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_name    text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_pin     text := btrim(coalesce(p_pin, ''));
  v_badge   text := nullif(btrim(coalesce(p_badge, '')), '');
  v_pending boolean := (select staff_signup_approval from public.settings where id = 1);
begin
  -- At most 6 sign-ups (or tries at a taken PIN) per device per hour.
  if p_ip_hash is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = p_ip_hash and kind = 'signup' and created_at > now() - interval '1 hour'
  ) >= 6 then
    return jsonb_build_object('error', 'Too many new accounts from this device. Try again later or ask a manager.');
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 40 then
    return jsonb_build_object('error', 'Enter your name.', 'field', 'name');
  end if;
  if v_pin !~ '^[0-9]{4}$' then
    return jsonb_build_object('error', 'Your PIN must be exactly 4 numbers.', 'field', 'pin');
  end if;
  if v_badge is not null and char_length(v_badge) > 40 then
    return jsonb_build_object('error', 'That student ID is too long.', 'field', 'badge');
  end if;
  if p_ip_hash is not null then
    insert into public.staff_clock_attempts (ip_hash, kind) values (p_ip_hash, 'signup');
  end if;
  if exists (select 1 from public.staff where status <> 'removed' and pin = v_pin) then
    return jsonb_build_object('error', 'That PIN is already taken. Pick a different one.', 'field', 'pin');
  end if;
  if v_badge is not null and exists (select 1 from public.staff where status <> 'removed' and lower(badge) = lower(v_badge)) then
    return jsonb_build_object('error', 'That student ID is already linked to an account.', 'field', 'badge');
  end if;
  begin
    insert into public.staff (name, pin, badge, status, self_signup)
    values (v_name, v_pin, v_badge, case when v_pending then 'pending' else 'active' end, true);
  exception when unique_violation then
    return jsonb_build_object('error', 'That PIN is already taken. Pick a different one.', 'field', 'pin');
  end;
  return jsonb_build_object('ok', true, 'pending', v_pending, 'name', v_name);
end;
$$;

-- What the time clock screen shows: who's on the clock, today's finished
-- shifts, and the schedule for the next two weeks. Names only.
create or replace function public.staff_board()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_tz    text := (select timezone from public.settings where id = 1);
  v_today date := public.store_today();
  v_start timestamptz := v_today::timestamp at time zone v_tz;
  v_time  time := public.store_now_time();
begin
  return jsonb_build_object(
    'onClock', (
      select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(s.name, sh.staff_name), 'in', sh.clock_in) order by sh.clock_in), '[]'::jsonb)
        from public.staff_shifts sh left join public.staff s on s.id = sh.staff_id
       where sh.clock_out is null
    ),
    'today', (
      select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'in', t.clock_in, 'out', t.clock_out) order by t.clock_out desc), '[]'::jsonb)
        from (
          select coalesce(s.name, sh.staff_name) as name, sh.clock_in, sh.clock_out
            from public.staff_shifts sh left join public.staff s on s.id = sh.staff_id
           where sh.clock_out is not null and sh.clock_in >= v_start
           order by sh.clock_out desc
           limit 20
        ) t
    ),
    -- A class hour stays on the list until about the end of it.
    'upcoming', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'date', u.work_date, 'label', u.label, 'startsAt', to_char(u.starts_at, 'HH24:MI'), 'name', u.name
             ) order by u.work_date, u.starts_at, u.sort_order, u.name), '[]'::jsonb)
        from (
          select sc.work_date, w.label, w.starts_at, w.sort_order, s.name
            from public.staff_schedule sc
            join public.pickup_windows w on w.id = sc.window_id
            join public.staff s on s.id = sc.staff_id and s.status = 'active'
           where sc.work_date between v_today and v_today + 14
             and (sc.work_date > v_today or w.starts_at > v_time - interval '50 minutes')
           order by sc.work_date, w.starts_at, s.name
           limit 80
        ) u
    ),
    'signupApproval', (select staff_signup_approval from public.settings where id = 1)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- 5. Security
-- -----------------------------------------------------------------------------
alter table public.staff                enable row level security;
alter table public.staff_shifts         enable row level security;
alter table public.staff_schedule       enable row level security;
alter table public.staff_credit_entries enable row level security;
alter table public.staff_clock_attempts enable row level security;

create policy "admin full access" on public.staff                for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.staff_shifts         for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.staff_schedule       for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.staff_credit_entries for all to authenticated using (public.is_admin()) with check (public.is_admin());
-- staff_clock_attempts: no policy at all, so only the database functions touch it.

revoke execute on function public.staff_credit_balances()            from public, anon;
revoke execute on function public.staff_credit_add(uuid, int, text)  from public, anon;
revoke execute on function public.staff_next_shift(uuid)             from public, anon, authenticated;
revoke execute on function public.staff_punch(text, text)            from public, anon, authenticated;
revoke execute on function public.staff_punch_undo(uuid, text)       from public, anon, authenticated;
revoke execute on function public.staff_signup(text, text, text, text) from public, anon, authenticated;
revoke execute on function public.staff_board()                      from public, anon, authenticated;

grant execute on function public.staff_credit_balances()             to authenticated, service_role;
grant execute on function public.staff_credit_add(uuid, int, text)   to authenticated;
grant execute on function public.staff_punch(text, text)             to service_role;
grant execute on function public.staff_punch_undo(uuid, text)        to service_role;
grant execute on function public.staff_signup(text, text, text, text) to service_role;
grant execute on function public.staff_board()                       to service_role;

